mapper.select:
select user_id, can_edit, can_publish, can_start
from wf_business_grant where business_code = #{code}
order by user_id

mapper.update:
update wf_business_grant
set can_edit = #{rights.edit}, can_publish = #{rights.publish}, can_start = #{rights.start}
where business_code = #{code} and user_id = #{userId}

mapper.insert:
insert into wf_business_grant (business_code, user_id, can_edit, can_publish, can_start)
select #{code}, id, #{rights.edit}, #{rights.publish}, #{rights.start}
from sys_user where id = #{userId}
